// llmenv hook bridge for opencode 2.x. Generated by llmenv; do not edit.
//
// The hook table is `llmenv-hooks.json` beside this file. Each hook gets the
// payload that Claude Code would send: a Claude tool name, Claude argument
// keys, and the session id of the call. A hook blocks a tool call by exit
// code 2 or by a `permissionDecision` of "deny" on stdout.
import { readFileSync } from "node:fs";
import { spawn } from "node:child_process";

const TABLE = JSON.parse(readFileSync(new URL("./llmenv-hooks.json", import.meta.url), "utf8"));
const DEFAULT_TIMEOUT_MS = 30000;

/** The project folder of the opencode instance, from the plugin context. */
let workDir = process.cwd();

/** The neutral tool name and Claude argument keys for an opencode tool call. */
export function toNeutral(tool, input) {
  const mapped = TABLE.tools[tool];
  if (mapped) return { name: mapped.name, input: renameKeys(input, mapped.args) };
  for (const [namespace, server] of Object.entries(TABLE.mcpServers)) {
    const prefix = `${namespace}_`;
    if (tool.startsWith(prefix)) {
      return { name: `mcp__${server}__${tool.slice(prefix.length)}`, input };
    }
  }
  return { name: tool, input };
}

/** `input` with the opencode keys put back, for an `updatedInput` from a hook. */
export function fromNeutral(tool, input) {
  const mapped = TABLE.tools[tool];
  if (!mapped) return input;
  const back = Object.fromEntries(Object.entries(mapped.args).map(([from, to]) => [to, from]));
  return renameKeys(input, back);
}

function renameKeys(input, renames) {
  if (input === null || typeof input !== "object" || Array.isArray(input)) return input;
  return Object.fromEntries(Object.entries(input).map(([k, v]) => [renames[k] ?? k, v]));
}

/** Whether a Claude-style matcher selects `toolName`. No matcher, "", and "*" select every tool. */
export function matches(matcher, toolName) {
  if (matcher === undefined || matcher === null || matcher === "" || matcher === "*") return true;
  return new RegExp(`^(?:${matcher})$`).test(toolName);
}

/**
 * Run every hook of `event` that selects `toolName`. Returns the joined
 * `additionalContext`, a block decision, an `updatedInput`, and the errors of
 * hooks that could not run.
 */
export async function runHooks(event, sessionID, extra, toolName) {
  const out = { context: [], errors: [], block: null, updatedInput: null };
  for (const hook of TABLE.hooks) {
    if (hook.event !== event) continue;
    if (toolName !== undefined) {
      try {
        if (!matches(hook.matcher, toolName)) continue;
      } catch (e) {
        out.errors.push(`llmenv: the matcher ${JSON.stringify(hook.matcher)} of a ${event} hook is not a valid pattern: ${e.message}`);
        continue;
      }
    }
    const payload = {
      hook_event_name: event,
      session_id: sessionID ?? "",
      cwd: workDir,
      ...extra,
    };
    let result;
    try {
      result = await spawnHook(hook.command, hook.timeout ?? DEFAULT_TIMEOUT_MS, payload);
    } catch (e) {
      out.errors.push(`llmenv: the ${event} hook \`${hook.command}\` could not run: ${e.message}`);
      continue;
    }
    readResult(event, hook.command, result, out);
    if (out.block) return out;
  }
  return out;
}

function readResult(event, command, result, out) {
  if (result.timedOut) {
    out.errors.push(`llmenv: the ${event} hook \`${command}\` timed out and was stopped`);
    return;
  }
  if (result.code === 2) {
    out.block = result.stderr || `Blocked by the llmenv hook \`${command}\``;
    return;
  }
  if (result.code !== 0) {
    const detail = result.stderr ? `: ${result.stderr}` : "";
    out.errors.push(`llmenv: the ${event} hook \`${command}\` exited with ${result.code}${detail}`);
  }
  if (!result.stdout) return;
  let parsed;
  try {
    parsed = JSON.parse(result.stdout);
  } catch {
    out.context.push(result.stdout);
    return;
  }
  const specific = parsed?.hookSpecificOutput ?? {};
  if (specific.permissionDecision === "deny") {
    out.block = specific.permissionDecisionReason || `Blocked by the llmenv hook \`${command}\``;
    return;
  }
  if (specific.updatedInput && typeof specific.updatedInput === "object") out.updatedInput = specific.updatedInput;
  if (typeof specific.additionalContext === "string" && specific.additionalContext.trim()) {
    out.context.push(specific.additionalContext);
  }
}

function spawnHook(command, timeoutMs, payload) {
  return new Promise((resolve, reject) => {
    const child = spawn("sh", ["-c", command], { stdio: ["pipe", "pipe", "pipe"] });
    let stdout = "";
    let stderr = "";
    let timedOut = false;
    const timer = setTimeout(() => {
      timedOut = true;
      child.kill("SIGKILL");
    }, timeoutMs);
    child.on("error", (e) => {
      clearTimeout(timer);
      reject(e);
    });
    child.stdout.on("data", (d) => (stdout += d.toString()));
    child.stderr.on("data", (d) => (stderr += d.toString()));
    child.on("close", (code) => {
      clearTimeout(timer);
      resolve({ code, timedOut, stdout: stdout.trim(), stderr: stderr.trim() });
    });
    // A hook that does not read stdin closes the pipe; that is not an error.
    child.stdin.on("error", () => {});
    child.stdin.end(JSON.stringify(payload));
  });
}

/** Per-session state: the SessionStart text, the current turn text, and errors to report. */
const sessions = new Map();

function state(sessionID) {
  let s = sessions.get(sessionID);
  if (!s) {
    s = { started: null, start: [], turn: [], errors: [], ended: false };
    sessions.set(sessionID, s);
  }
  return s;
}

function startSession(sessionID) {
  const s = state(sessionID);
  if (!s.started) {
    s.started = runHooks("SessionStart", sessionID, { source: "startup" }).then((out) => {
      s.start = out.context;
      s.errors.push(...out.errors);
    });
  }
  return s.started;
}

async function endSession(sessionID) {
  const s = sessions.get(sessionID);
  if (!s || s.ended) return;
  s.ended = true;
  await runHooks("SessionEnd", sessionID, {});
  sessions.delete(sessionID);
}

/** The system parts for the next request: SessionStart text, turn text, and hook errors. */
export function systemParts(sessionID) {
  const s = sessions.get(sessionID);
  if (!s) return [];
  const errors = s.errors.splice(0);
  return [...s.start, ...s.turn, ...errors].map((text) => ({ type: "text", text }));
}

async function onEvent(ev) {
  const sessionID = ev?.data?.sessionID;
  if (!sessionID) return;
  if (ev.type === "session.created") await startSession(sessionID);
  else if (ev.type === "session.execution.succeeded") {
    const out = await runHooks("Stop", sessionID, { stop_hook_active: false });
    state(sessionID).errors.push(...out.errors);
  } else if (ev.type === "session.deleted") await endSession(sessionID);
}

export default {
  id: "llmenv",
  setup: async (ctx) => {
    if (ctx.location?.directory) workDir = ctx.location.directory;
    await ctx.tool.hook("execute.before", async (e) => {
      await startSession(e.sessionID);
      const neutral = toNeutral(e.tool, e.input ?? {});
      const out = await runHooks("PreToolUse", e.sessionID, { tool_name: neutral.name, tool_input: neutral.input }, neutral.name);
      state(e.sessionID).errors.push(...out.errors);
      if (out.block) throw new Error(out.block);
      if (out.updatedInput) e.input = fromNeutral(e.tool, out.updatedInput);
      if (out.context.length) state(e.sessionID).turn.push(...out.context);
    });
    await ctx.tool.hook("execute.after", async (e) => {
      const neutral = toNeutral(e.tool, e.input ?? {});
      const response = e.status === "completed" ? e.result : { error: String(e.error?.message ?? e.error) };
      const out = await runHooks("PostToolUse", e.sessionID, { tool_name: neutral.name, tool_input: neutral.input, tool_response: response }, neutral.name);
      const s = state(e.sessionID);
      s.errors.push(...out.errors);
      if (out.context.length) s.turn.push(...out.context);
    });
    await ctx.session.hook("prompt", async (e) => {
      await startSession(e.sessionID);
      const out = await runHooks("UserPromptSubmit", e.sessionID, { prompt: e.prompt?.text ?? "" });
      const s = state(e.sessionID);
      s.turn = out.context;
      s.errors.push(...out.errors);
      if (out.block) throw new Error(out.block);
    });
    await ctx.session.hook("context", async (e) => {
      e.system.push(...systemParts(e.sessionID));
    });
    // Not awaited: setup must return, and the event stream never ends.
    void (async () => {
      for await (const ev of ctx.event.subscribe()) {
        await onEvent(ev).catch((err) => console.error(`llmenv: an event hook failed: ${err.message}`));
      }
    })().catch((err) => console.error(`llmenv: the event stream stopped, so SessionStart, Stop, and SessionEnd hooks no longer run: ${err.message}`));
    return async () => {
      await Promise.all([...sessions.keys()].map(endSession));
    };
  },
};
